  "faq_s_a3": "ਪੂਰਾ 4-Camera ਸੈੱਟਅੱਪ ਬ੍ਰਾਂਡ ਅਤੇ ਮਾਡਲ ਮੁਤਾਬਕ ਲਗਭਗ ₹14,200 ਤੋਂ ₹18,000 ਤੋਂ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ। 18% GST, ਤਾਰ ਅਤੇ Fitting ਸਭ ਸ਼ਾਮਲ ਹੈ।",
  "faq_s_a4": "ਹਾਂ। CP Plus ਅਤੇ Prama ਮਾਡਲ BIS-ER ਪ੍ਰਮਾਣਿਤ ਹਨ — ਘਰ, ਦੁਕਾਨ, ਸੋਸਾਇਟੀ ਅਤੇ ਸਰਕਾਰੀ ਟੈਂਡਰਾਂ ਲਈ ਢੁਕਵੇਂ ਹਨ। STQC ਵਿਕਲਪ ਵੀ ਮਿਲਦੇ ਹਨ।",
