  "legal_terms_body": "ਕੋਟੇਸ਼ਨ ਵਿੱਚ 18% GST, ਅਸਲੀ ਸੀਲਬੰਦ ਹਾਰਡਵੇਅਰ ਅਤੇ ਸਟੈਂਡਰਡ ਕੇਬਲ (15m/ਕੈਮਰਾ) ਸ਼ਾਮਲ ਹੈ। ਭੁਗਤਾਨ ਦੇ ਪੜਾਅ: ₹500 ਬੁਕਿੰਗ ਟੋਕਨ, ਸਾਮਾਨ ਡਿਲੀਵਰੀ 'ਤੇ 90% ਅਤੇ ਮੋਬਾਈਲ 'ਤੇ ਲਾਈਵ ਟੈਸਟਿੰਗ ਤੋਂ ਬਾਅਦ 10%। ਹਾਰਡਵੇਅਰ 'ਤੇ ਬ੍ਰਾਂਡ ਵਾਰੰਟੀ ਤੇ 1 ਸਾਲ ਦੀ ਸਰਵਿਸ ਸਪੋਰਟ ਮਿਲਦੀ ਹੈ।",
